{
  "schemaVersion": 1,
  "date": "2026-10-23",
  "interview": [
    {
      "id": "interview-01",
      "articleIds": [
        "2026-10-23-top-1"
      ],
      "question": "大きなリポジトリでAIエージェントの並列開発を支えるには、何を設計しますか。",
      "answer": "大きなコードベースでは、並列開発を支える実行環境も設計します。haroはTemporalで処理の流れを管理し、EKS上の環境を専用コントローラーで運用しています。社内MCPは利用者のアカウントで接続します。ただしPR作成割合は普及の指標であり、品質向上の証明とは分けて考えます。"
    },
    {
      "id": "interview-02",
      "articleIds": [
        "2026-10-23-top-2"
      ],
      "question": "日本語のRAG回答に評価機構を導入するとき、何を確かめますか。",
      "answer": "回答の根拠と質問への関連性を別々に確かめます。記事では両方のしきい値を0.7にそろえ、ClassicとStandardを同じ四つの回答で比較しました。ただし少数例の結果なので、日本語対応だけで正確さを保証せず、誤った金額や答えていない回答も評価します。"
    },
    {
      "id": "interview-03",
      "articleIds": [
        "2026-10-23-top-3"
      ],
      "question": "Reactの変更がビルド結果へ反映されない場合、どう調べますか。",
      "answer": "まず、変更したファイルが実際に読み込まれているかを調べます。記事ではtscの出力した古いJavaScriptが、ViteでTSXより先に選ばれていました。noEmitの指定と同名ファイルを確認し、不要な生成物だけを片付けます。ビルド成功だけでは反映された保証になりません。"
    },
    {
      "id": "interview-04",
      "articleIds": [
        "2026-10-23-top-4"
      ],
      "question": "アニメーションに外部データを結び付けるとき、どこを検証しますか。",
      "answer": "値の型だけでなく、変換と描画結果も確認します。RiveではViewModelを定義し、rangeMapperでHPの0から100を拡大率の0から1へ変換しています。ただしファイルが作れても、別の値で正しく描けるとは限りません。文字の差し替えには、フォントへ残す文字の確認も必要です。"
    },
    {
      "id": "interview-05",
      "articleIds": [
        "2026-10-23-top-5"
      ],
      "question": "AIが書いたテストが通った後、検出力をどう確かめますか。",
      "answer": "意図的に小さな変更を入れ、テストが気付くかを見ます。MutantKitではselectCoveringTestsを有効にし、実行したのに検出しなかった結果と、実行していないnoCoverageを分けます。ただし等価な変更はテストを増やしても検出できません。仕様に必要な振る舞いから追加を判断します。"
    }
  ],
  "review": [
    {
      "id": "review-01",
      "articleIds": [
        "2026-10-23-top-1",
        "2026-10-23-top-5"
      ],
      "question": "PR作成割合やgreenなテストだけで品質向上を判断できますか。",
      "points": {
        "zh": "不能。haro的数字反映PR创建渠道；变异测试还要确认修改真正进入产物，区分未覆盖、未检出及无效试验。",
        "ja": "haroの割合はPRの作成経路です。品質とは分け、変異テストでも変更の反映、未実行、未検出、無効な試験を区別します。"
      }
    },
    {
      "id": "review-02",
      "articleIds": [
        "2026-10-23-top-2"
      ],
      "question": "複数ターンの回答評価で、過去の会話をそのまま根拠にしてよいですか。",
      "points": {
        "zh": "不能混淆模型历史与评估用输入。原文把用户提问整理至1000字符，资料另行标记；助手旧回答不能成为可靠资料，跨区域要求也需单独检查。",
        "ja": "モデルの履歴と評価用の入力は別です。利用者の発言を1000文字に収め、資料を分け、過去の助手回答を根拠にしません。推論先の条件も確認します。"
      }
    },
    {
      "id": "review-03",
      "articleIds": [
        "2026-10-23-top-3",
        "2026-10-23-top-4"
      ],
      "question": "作成した成果物に意図した変更が入ったことを、どう確かめますか。",
      "points": {
        "zh": "Vite需确认真实解析到的输入和产物文字；Rive需检查父引用结构、不同数据值的画面及必要字符，不能只看文件存在。",
        "ja": "Viteでは実際の入力と出力内容を確認します。Riveでは親参照、値を変えた描画、必要な文字を調べ、ファイル作成だけで終えません。"
      }
    }
  ]
}
